(()=>{'use strict';const $=id=>document.getElementById(id),key='zuxuru-fashion-service-v1',money=['materials','labour','production','packCost','delivery','other'];let state={designer:{},products:[],evidence:[],orders:[]};try{const s=JSON.parse(localStorage.getItem(key));if(valid(s))state=s;}catch{}
function valid(s){return s&&s.designer&&typeof s.designer==='object'&&['products','evidence','orders'].every(k=>Array.isArray(s[k])&&s[k].length<=500&&s[k].every(v=>v&&typeof v==='object'&&typeof v.id==='string'));}
const node=(t,text)=>{const n=document.createElement(t);if(text!==undefined)n.textContent=text;return n;},esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function url(v){try{const u=new URL(v);return ['https:','http:'].includes(u.protocol)&&!u.username&&!u.password?u.href:'';}catch{return '';}}
function save(){try{localStorage.setItem(key,JSON.stringify(state));$('status').textContent='Saved in this browser. Export a backup to keep your work.';}catch{$('status').textContent='Storage unavailable. Export your workspace before leaving.';}}
function removeButton(collection,id){const b=node('button','Remove');b.onclick=()=>{if(confirm('Remove this record?')){state[collection]=state[collection].filter(v=>v.id!==id);save();render();}};return b;}
function form(id,collection){$(id).onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));for(const k of Object.keys(v)){if(k.endsWith('URL')||k==='url'||k==='image')v[k]=url(v[k]);}if(collection==='products')for(const k of [...money,'price'])v[k]=v[k]===''?null:Number(v[k]);v.id=collection==='products'&&e.target.dataset.editId?e.target.dataset.editId:crypto.randomUUID();if(collection==='orders')v.stage='Enquiry';const existing=state[collection].findIndex(r=>r.id===v.id);if(existing>=0)state[collection][existing]={...state[collection][existing],...v};else state[collection].push(v);delete e.target.dataset.editId;save();e.target.reset();if(collection==='products')e.target.querySelector('button').textContent='Add product';render();};}
$('designer-form').onsubmit=e=>{e.preventDefault();const designer=Object.fromEntries(new FormData(e.target));designer.name=String(designer.name||'').trim();const input=e.target.elements.name;input.setCustomValidity(designer.name?'':'Enter your designer or brand name.');if(!input.reportValidity())return;state.designer=designer;state.designer.url=url(state.designer.url);save();try{const persisted=JSON.parse(localStorage.getItem(key));if(persisted?.designer?.name===state.designer.name)sessionStorage.removeItem('bonga-profile-name');}catch{}};
$('designer-form').elements.name.addEventListener('input',e=>e.target.setCustomValidity(''));
try{const pending=sessionStorage.getItem('bonga-profile-name');if(pending&&!state.designer.name){$('designer-form').elements.name.value=pending;}}catch{}
Object.entries(state.designer).forEach(([k,v])=>{if($('designer-form').elements[k])$('designer-form').elements[k].value=v;});form('product-form','products');form('evidence-form','evidence');form('order-form','orders');
document.addEventListener('fashion-storefront-updated',()=>{const incoming=JSON.parse(localStorage.getItem(key));if(valid(incoming)){state=incoming;render();}});
document.addEventListener('fashion-evidence-checked',event=>{state.evidenceChecks=event.detail;save();});
document.addEventListener('fashion-open-order',event=>{const id=event.detail?.id;if(typeof id!=='string')return;const card=Array.from($('order-list').querySelectorAll('[data-order-id]')).find(card=>card.dataset.orderId===id);if(!card){$('status').textContent='This task’s source order is no longer in your saved workspace. Review the task before taking action.';return;}location.hash='orders';card.focus({preventScroll:true});card.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'center'});});
document.addEventListener('fashion-enquiry-import',event=>{const e=event.detail;if(!state.orders.some(o=>o.id===e.id)){state.orders.push({id:e.id,customer:e.name,request:e.product,next:e.message+' · Reply to: '+e.contact,due:'',stage:'Enquiry'});save();render();}});
function render(){for(const collection of ['products','evidence','orders']){const target=$(collection==='evidence'?'sources':collection==='orders'?'order-list':'products');target.replaceChildren();if(!state[collection].length)target.append(node('p','No records yet. Add your own confirmed details above.'));state[collection].forEach(v=>{const card=node('article');card.className='record';card.append(node('h3',v.name||v.customer||v.type));if(collection==='products'){const image=url(v.image);if(image){const img=node('img');img.src=image;img.alt=v.name;img.loading='lazy';card.append(img);}card.append(node('p',`${v.sizes||'Sizes not recorded'} · ${v.colours||'Colours not recorded'} · ${v.availability}`));const known=money.every(k=>Number.isFinite(v[k]))&&Number.isFinite(v.price);card.append(node('p',known?`Recorded cost R${money.reduce((a,k)=>a+v[k],0).toFixed(2)} · Unit contribution R${(v.price-money.reduce((a,k)=>a+v[k],0)).toFixed(2)} · ${v.price>0?((v.price-money.reduce((a,k)=>a+v[k],0))/v.price*100).toFixed(1)+'%':'Margin undefined'}`:'Cost and margin unknown until every cost and selling price is recorded. Enter 0 only when confirmed.'));card.append(node('p',v.description));}
if(collection==='evidence'){card.append(node('p',v.note),node('p','Checked: '+v.date));const u=url(v.url);if(u){const a=node('a','Open source ↗');a.href=u;a.target='_blank';a.rel='noopener noreferrer';card.append(a);const connect=node('a','Review platform connection');connect.href='#connections';connect.style.display='block';connect.onclick=()=>{document.getElementById('connection-source').textContent='Public evidence: '+u+' · '+v.note;};card.append(connect);}}
if(collection==='orders'){card.dataset.orderId=v.id;card.tabIndex=-1;card.append(node('p',v.request));const label=node('label','Current stage'),select=node('select');['Enquiry','Consultation','Quote','Follow-up','Closer review','Order agreed','Payment recorded','Design approved','Production','Quality check','Packaging','Dispatched','Delivered','Closed'].forEach(x=>select.append(new Option(x,x)));select.value=v.stage;select.onchange=()=>{v.stage=select.value;save();};label.append(select);card.append(label);const fulfilment=node('details');fulfilment.append(node('summary','Quote, production & delivery details'));for(const [k,title] of [['next','Next action'],['due','Target delivery date'],['quote','Quote / agreed scope'],['measurements','Measurements / fit notes'],['approval','Design approval evidence'],['production','Production partner / progress'],['quality','Quality checks'],['packaging','Packaging instructions'],['delivery','Delivery address / arrangements'],['tracking','Courier / tracking reference'],['payment','Payment evidence / amount']]){const l=node('label',title),input=node(k==='due'?'input':'textarea');if(k==='due')input.type='date';input.value=v[k]||'';input.maxLength=1000;input.onchange=()=>{v[k]=input.value;save();};l.append(input);(k==='next'||k==='due'?card:fulfilment).append(l);}card.append(fulfilment);const exportOrder=node('button','Download production & delivery brief');exportOrder.type='button';exportOrder.onclick=()=>{const d=state.designer||{},field=(label,value)=>label+': '+(String(value??'').trim()||'Not recorded'),brief=['BONGA BHENGU / FASHION ORDER BRIEF',field('Designer / brand',d.name),field('Business contact',d.email),field('Business location',d.location),'',field('Order reference',v.id),field('Customer / enquiry',v.customer),field('Garment / request',v.request),field('Recorded stage',v.stage),field('Target delivery date',v.due),'',field('Quote / agreed scope',v.quote),field('Measurements / fit',v.measurements),field('Design approval evidence',v.approval),field('Production partner / progress',v.production),field('Quality checks',v.quality),field('Packaging instructions',v.packaging),field('Delivery address / arrangements',v.delivery),field('Payment evidence / amount',v.payment),field('Courier / tracking',v.tracking),field('Next action',v.next),'','Internal brief from your saved records. Review measurements, approval, payment and timing before production.'].join('\n');download(brief,'order-'+String(v.id||'brief').replace(/[^a-zA-Z0-9_-]/g,'').slice(0,80)+'.txt','text/plain');$('status').textContent='Order brief downloaded for review. Share it with your chosen production or delivery partner when ready.';};card.append(exportOrder);const closer=node('button','Review customer sales brief');closer.type='button';closer.onclick=()=>document.dispatchEvent(new CustomEvent('fashion-review-closer',{detail:{id:v.id}}));card.append(closer);}
if(collection==='products'){const edit=node('button','Edit product');edit.onclick=()=>{const f=$('product-form');f.reset();Object.entries(v).forEach(([k,value])=>{if(f.elements[k])f.elements[k].value=value??'';});f.dataset.editId=v.id;f.querySelector('button').textContent='Save product changes';location.hash='catalogue';f.scrollIntoView({behavior:'smooth'});};card.append(edit);}card.append(removeButton(collection,v.id));target.append(card);});}}
function storefront(){const d=state.designer;if(!d.name)throw Error('Save your designer profile first.');const email=/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(d.email||'')?d.email:'';const cards=state.products.map(p=>{const image=url(p.image),body='I would like to enquire about '+p.name+'.\nSize / measurements:\nColour:\nRequired date:\nPlease confirm price and availability.';const enquiry=email?`<a href="mailto:${esc(email)}?subject=${encodeURIComponent('Fashion enquiry: '+p.name)}&body=${encodeURIComponent(body)}">Enquire about this design</a>`:'<p>Contact details pending.</p>';return `<article>${image?`<img src="${esc(image)}" alt="${esc(p.name)}">`:''}<h2>${esc(p.name)}</h2><p>${esc(p.description)}</p><p>Sizes: ${esc(p.sizes||'Discuss with designer')} · Colours: ${esc(p.colours||'Discuss with designer')}</p><p>${esc(p.availability)}</p><strong>${Number.isFinite(p.price)?'R'+p.price.toFixed(2):'Quote required'}</strong><p>${esc(p.leadtime||'Production and delivery timing to be confirmed.')}</p>${enquiry}</article>`;}).join('');return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="${esc(d.style||'Designer fashion collection')}"><title>${esc(d.name)} · Designer Fashion</title><style>body{margin:0;background:#f6f2e9;color:#18191c;font-family:Arial,sans-serif}header,main,footer{max-width:1100px;margin:auto;padding:35px}h1{font:60px Georgia,serif}p{line-height:1.7}section{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:25px}article{background:white;padding:25px}img{width:100%;height:320px;object-fit:cover}a{display:inline-block;background:#18191c;color:#f1dec0;padding:13px 17px;text-decoration:none;margin-top:15px}footer{font-size:12px}@media(max-width:600px){h1{font-size:38px}header,main,footer{padding:20px}}</style></head><body><header><p>${esc(d.location)}</p><h1>${esc(d.name)}</h1><p>${esc(d.style)}</p><p>${esc(d.story)}</p>${url(d.url)?`<a href="${esc(url(d.url))}">View my portfolio</a>`:''}</header><main><section>${cards||'<p>Collection coming soon.</p>'}</section></main><footer>Custom orders are subject to agreed brief, quote, payment and production timing. Generated with Zuxuru for Fashion Designers.</footer></body></html>`;}
function download(text,name,type){const u=URL.createObjectURL(new Blob([text],{type}));const a=node('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
$('build').onclick=()=>{try{$('preview').srcdoc=storefront();$('preview').hidden=false;$('status').textContent='Storefront generated. Preview before downloading; it has not been published.';}catch(e){$('status').textContent=e.message;}};
$('download').onclick=()=>{try{download(storefront(),'designer-storefront.html','text/html');}catch(e){$('status').textContent=e.message;}};
$('campaign').onclick=()=>{$('caption').hidden=false;$('caption').value=`Introducing ${state.designer.name||'[your brand]'}\n${state.designer.style||'[your speciality]'}\n${state.designer.story||'[your story]'}\nExplore ${state.products.map(p=>p.name).join(', ')||'[your collection]'}.\nSend your size, colour preference and required date to discuss a custom order. Price and availability confirmed with your quote.\n${state.designer.email||'[your contact]'}`;};
$('backup').onclick=()=>download(JSON.stringify({format:key,...state},null,2),'zuxuru-fashion-workspace.json','application/json');
$('restore').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>2000000)throw Error();const s=JSON.parse(await f.text());if(s.format!==key||!valid(s))throw Error();if(!confirm('Replace this workspace with the backup?'))return;state={designer:s.designer,products:s.products,evidence:s.evidence,orders:s.orders,storefront:s.storefront||{}};save();Object.entries(state.designer).forEach(([k,v])=>{if($('designer-form').elements[k])$('designer-form').elements[k].value=v;});render();}catch{$('status').textContent='Backup not restored. Select a valid fashion workspace backup.';}e.target.value='';};render();
})();
